package com.aurahealth.model;

/**
 * Base User Domain Entity.
 * <p>
 * Encapsulates core user account credentials and personal profile information:
 * <ul>
 *   <li>{@code id}: Primary key generated by the database.</li>
 *   <li>{@code name}: Full legal name of the patient or staff member.</li>
 *   <li>{@code email}: Unique email identifier for authentication and notifications.</li>
 *   <li>{@code role}: Role-based access level ('patient', 'doctor', or 'admin').</li>
 *   <li>{@code phone}: Contact mobile number.</li>
 * </ul>
 * Demonstrates the <b>Inheritance</b> pillar of OOP: specialized user types such as
 * {@link Doctor} extend this class with clinical attributes.
 * </p>
 */
public class User {

    private int id;
    private String name;
    private String email;
    private String role;
    private String phone;

    /**
     * Constructs a new User instance.
     *
     * @param id primary key identifier
     * @param name user full name
     * @param email unique email address
     * @param role security role ('patient', 'doctor', 'admin')
     * @param phone contact telephone number
     */
    public User(int id, String name, String email, String role, String phone) {
        this.id = id;
        this.name = name;
        this.email = email;
        this.role = role;
        this.phone = phone;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getRole() {
        return role;
    }

    public void setRole(String role) {
        this.role = role;
    }

    public String getPhone() {
        return phone;
    }

    public void setPhone(String phone) {
        this.phone = phone;
    }
}

